import pandas as pd
import numpy as np

# Load the GHG data for 33 London boroughs into a pandas DataFrame
ghg_data = pd.read_csv('getisord_2023_ghg.csv')

# Load the list of neighboring boroughs for each borough into a separate pandas DataFrame
adjacency_data = pd.read_csv('borough_adjacency.csv')

# Create a dictionary to store the neighbors for each borough
neighbors_dict = {}
for index, row in adjacency_data.iterrows():
    if row['borough'] not in neighbors_dict:
        neighbors_dict[row['borough']] = []
    neighbors_dict[row['borough']].append(row['neighbor'])

# Create a new DataFrame that combines each borough with its neighbors
combined_data = ghg_data.copy()
for borough, neighbors in neighbors_dict.items():
    combined_data.loc[borough, 'neighbor_sum'] = combined_data.loc[borough, 'GHG_value'] + sum([ghg_data.loc[neighbor, 'GHG_value'] for neighbor in neighbors])

# Calculate the citywide average
citywide_average = combined_data['neighbor_sum'].mean()

# Apply the Getis-Ord Gi* method
gi_values = []
for index, row in combined_data.iterrows():
    if not np.isnan(row['GHG_value']):
        gi_value = (row['neighbor_sum'] - citywide_average) / (citywide_average * (1 + (row['neighbor_sum'] / citywide_average)))
        gi_values.append(gi_value)

# Identify statistically significant hot and cold spots
critical_values = {
    '95% confidence': 1.96,
    '99% confidence': 2.576
}
significant_spots = []
for i, gi_value in enumerate(gi_values):
    if abs(gi_value) > critical_values['95% confidence']:
        significant_spots.append((combined_data.index[i], 'HOT', gi_value, gi_value))
    elif abs(gi_value) < -critical_values['95% confidence']:
        significant_spots.append((combined_data.index[i], 'COLD', gi_value, gi_value))

# Print the results
